      body.querySelectorAll('[data-igmostra]').forEach(b=>b.onclick=async()=>{try{await adminApi('/integrations/meta/account',{ocultar:(ig.ocultas||[]).filter(x=>x!==b.dataset.igmostra)});renderAdministration()}catch(e){toast(e.message,'warn')}});
