        $('#adsListar',body).onclick=async()=>{try{await adminApi('/integrations/ads/accounts');toast('Contas atualizadas');renderAdministration()}catch(x){toast(x.message,'warn')}};
        $('#adsSalvarConta',body).onclick=async()=>{const v=$('#adsConta',body).value;if(!v)return toast('Busque as contas primeiro','warn');try{await adminApi('/integrations/ads/account',{conta:v});toast('Conta escolhida');renderAdministration()}catch(x){toast(x.message,'warn')}};
        $('#adsSyncBtn',body).onclick=async()=>{const b=$('#adsSyncBtn',body);b.disabled=true;b.textContent='Sincronizando…';try{const r=await adminApi('/integrations/ads/sync',{});toast(r.linhas+' linha(s) atualizadas');renderAdministration()}catch(x){toast(x.message,'warn');renderAdministration()}};
        $('#lmSalvar',body).onclick=async()=>{try{await adminApi('/integrations/ads/config',{ctrMin:+$('#lmCtr',body).value,frequenciaMax:+$('#lmFreq',body).value,gastoSemResultado:+$('#lmGasto',body).value,impressoesMin:+$('#lmImpr',body).value});toast('Limites salvos');renderAdministration()}catch(x){toast(x.message,'warn')}};
        const aut2=async()=>{try{await adminApi('/admin/automacoes',{auto_tarefa_solicitacao:$('#autTarefa',body).checked,auto_recorrencia:$('#autRec',body).checked});toast('Automações salvas')}catch(x){toast(x.message,'warn')}};
