      const run=(sel,path,msg)=>{const el=$(sel);if(el)el.onclick=async()=>{el.disabled=true;toast('Processando…');try{const r=await adminApi(path,{});toast(typeof msg==='function'?msg(r):msg);renderAdministration()}catch(e){toast(e.message,'bad');el.disabled=false;renderAdministration()}}};
      run('#igSync','/integrations/instagram/sync',r=>`${r.periodos} período(s) atualizados na tela Instagram`);
      run('#gCal','/integrations/google/calendar/sync',r=>`Agenda: ${r.para_google} enviados, ${r.do_google} alterados pelo Google, ${r.criados} novos, ${r.removidos} removidos`);
      run('#gSheet','/integrations/google/sheets/export',r=>`Planilha atualizada (${Object.keys(r.abas).length} abas)`);
      run('#gDrive','/integrations/google/drive/send-entregas',r=>`${r.arquivos} arquivo(s) enviados ao Drive`);
      const disc=(sel,path)=>{const el=$(sel);if(el)el.onclick=async()=>{if(!confirm('Desconectar? As credenciais salvas continuam; apenas o acesso é removido.'))return;await adminApi(path,{});renderAdministration()}};disc('#igDisc','/integrations/meta/disconnect');disc('#gDisc','/integrations/google/disconnect');
      $('#igManual')&&($('#igManual').onclick=async()=>{const tok=prompt('Cole o token de acesso (de usuário do sistema ou de longa duração):');if(!tok)return;const id=prompt('ID da conta Instagram profissional (deixe vazio para descobrir automaticamente):')||'';try{await adminApi('/integrations/meta/token',{token:tok,ig_user_id:id});toast('Token salvo');renderAdministration()}catch(e){toast(e.message,'bad')}});
      $('#gCalCarregar')&&($('#gCalCarregar').onclick=async ev=>{try{const r=await adminApi('/integrations/google/calendars');const sel=$('#gCalSel');if(!sel)return;const escolhido=sel.dataset.tocou?sel.value:null;sel.innerHTML='<option value="">Nenhuma (Agenda desligada)</option>'+(r.rows||[]).map(a=>`<option value="${attr(a.id)}" ${a.atual?'selected':''}>${esc(a.nome)}${a.principal?' (principal)':''}</option>`).join('');if(escolhido!==null)sel.value=escolhido;if(ev&&ev.isTrusted)toast((r.rows||[]).length+' agenda(s) encontradas')}catch(e){if(ev&&ev.isTrusted)toast(e.message,'bad')}});
      $('#gCalSel')&&($('#gCalSel').onchange=e=>{e.target.dataset.tocou='1'});
      $('#gCalSalvar')&&($('#gCalSalvar').onclick=async()=>{const v=$('#gCalSel').value;if(!confirm(v?'Usar esta agenda? Os eventos dela passam a sincronizar com o sistema.':'Desligar a sincronização da Agenda?'))return;try{await adminApi('/integrations/google/calendar/choose',{id:v});toast('Agenda definida. Clique em Sincronizar Agenda.');renderAdministration()}catch(e){toast(e.message,'bad')}});
      $('#gCalCarregar')&&$('#gCalCarregar').click();
      $('#gImportar')&&($('#gImportar').onchange=async e=>{try{await adminApi('/integrations/settings',{g_importar:e.target.checked});toast(e.target.checked?'Importação do Google ligada':'Importação do Google desligada')}catch(x){toast(x.message,'bad')}});
      $('#gCalLimpar')&&($('#gCalLimpar').onclick=async()=>{if(!confirm('Remover do SISTEMA os eventos que vieram do Google? Nada é apagado no Google.'))return;try{const r=await adminApi('/integrations/google/calendar/limpar-importados',{});invalidate('calendario');toast(r.removidos+' item(ns) removidos do sistema. O Google não foi alterado.');renderAdministration()}catch(x){toast(x.message,'bad')}});
      $('#gAuto')&&($('#gAuto').onchange=async e=>{await adminApi('/integrations/settings',{g_auto_drive_entregas:e.target.checked});toast(e.target.checked?'Envio automático ao Drive ligado':'Envio automático desligado')});
      $$('.ig-media',body).forEach(b=>b.onclick=()=>{const inp=document.createElement('input');inp.type='file';inp.accept='.jpg,.jpeg,.mp4,.mov,image/jpeg,video/mp4,video/quicktime';inp.onchange=async()=>{const fd=new FormData();fd.append('files',inp.files[0]);try{const r=await fetch('/api/integrations/instagram/media?id='+encodeURIComponent(b.dataset.id),{method:'POST',credentials:'same-origin',headers:{'X-EVO':'1'},body:fd});const j=await r.json();if(!r.ok)throw new Error(j.error);invalidate('conteudos');toast('Mídia anexada');renderAdministration()}catch(e){toast(e.message,'bad')}};inp.click()});
